import Link from 'next/link';
import { notFound } from 'next/navigation';
import { getApplicationById } from '@/lib/applications';
import { formatDate } from '@/lib/format';
import StatusBadge from '@/components/status-badge';
import type { Permit } from '@/generated/prisma/enums';

const permitLabels: Record<Permit, string> = {
    YES: 'Supports work permits',
    NO: 'No work permit support',
    UNKNOWN: 'Unknown',
};

// PageProps is generated by Next from the folder path, so `id` is typed for us.
const ApplicationDetailPage = async (props: PageProps<'/applications/[id]'>) => {
    // `id` comes from the URL: /applications/abc → id = 'abc' (always a string).
    const { id } = await props.params;
    const application = await getApplicationById(id);

    // Unknown id → render the 404 page and stop here (notFound() throws).
    if (!application) {
        notFound();
    }

    const fields: [string, string | null][] = [
        ['Applied on', formatDate(application.appliedAt)],
        ['Salary range', application.salaryRange],
        ['Recruiter', application.recruiterName],
        ['Email used', application.emailUsed],
        ['Work permit', permitLabels[application.permitSupport]],
        ['Added', formatDate(application.createdAt)],
    ];

    return (
        <main className="mx-auto max-w-3xl px-4 py-8 sm:px-6">
            <Link href="/applications" className="text-sm text-zinc-500 transition-colors hover:text-zinc-900 dark:hover:text-white">
                ← All applications
            </Link>

            <div className="mt-4 rounded-xl border border-zinc-200 bg-white shadow-sm dark:border-zinc-800 dark:bg-zinc-900">
                <div className="flex flex-wrap items-start justify-between gap-4 border-b border-zinc-200 p-6 dark:border-zinc-800">
                    <div className="flex items-center gap-4">
                        <span className="flex h-12 w-12 items-center justify-center rounded-lg bg-zinc-100 text-lg font-semibold text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300">
                            {application.company.charAt(0)}
                        </span>
                        <div>
                            <h1 className="text-xl font-semibold tracking-tight">{application.company}</h1>
                            <p className="text-zinc-500">{application.role}</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <StatusBadge status={application.status} />
                        {application.jobUrl && (
                            <a
                                href={application.jobUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="rounded-md border border-zinc-300 px-3 py-1.5 text-sm font-medium transition-colors hover:bg-zinc-50 dark:border-zinc-700 dark:hover:bg-zinc-800"
                            >
                                View job post ↗
                            </a>
                        )}
                    </div>
                </div>

                <dl className="grid gap-x-6 gap-y-5 p-6 sm:grid-cols-2">
                    {fields.map(([label, value]) => (
                        <div key={label}>
                            <dt className="text-xs font-medium uppercase tracking-wide text-zinc-500">{label}</dt>
                            <dd className="mt-1 break-words">{value ?? '—'}</dd>
                        </div>
                    ))}
                </dl>

                <div className="border-t border-zinc-200 p-6 dark:border-zinc-800">
                    <h2 className="text-xs font-medium uppercase tracking-wide text-zinc-500">Notes</h2>
                    <p className="mt-2 whitespace-pre-wrap">{application.notes ?? 'No notes yet.'}</p>
                </div>
            </div>
        </main>
    );
}

export default ApplicationDetailPage;
